import sys, os, json, importlib.util

repo = '/testbed'
test_file = '/testbed/qa_instances_eval/pybamm_qa/base_solver_solve_call_coverage_suite/files/tests/qa/base_solver_solve_call_coverage_suite_test.py'

spec = importlib.util.spec_from_file_location('qa_suite', test_file)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

cls = mod.TestBaseSolverSolveCallCoverageQA
obj = cls()

prefixes = (
    'pybamm.solvers.',
    'pybamm.models.base_model.',
    'pybamm.models.event.',
    'pybamm.expression_tree.',
)

covered = set()
active_target_depth = 0
# stack of booleans to detect returns for target frames
is_target_frame_stack = {}

TARGET_MOD = 'pybamm.solvers.base_solver'
TARGET_QN = 'BaseSolver.solve'

def norm_rel(path):
    path = os.path.abspath(path)
    rel = os.path.relpath(path, repo)
    return rel.replace(os.sep, '/')

def under_src_pybamm(path):
    path = os.path.abspath(path)
    src = os.path.abspath(os.path.join(repo, 'src', 'pybamm'))
    try:
        common = os.path.commonpath([path, src])
    except ValueError:
        return False
    if common != src:
        return False
    rel = os.path.relpath(path, src).replace(os.sep, '/')
    if rel.startswith('tests/'):
        return False
    return True


def profiler(frame, event, arg):
    global active_target_depth
    if event == 'call':
        modname = frame.f_globals.get('__name__', '')
        qual = frame.f_code.co_qualname
        is_target = (modname == TARGET_MOD and qual == TARGET_QN)
        if is_target:
            active_target_depth += 1
            is_target_frame_stack[id(frame)] = True
        else:
            is_target_frame_stack[id(frame)] = False

        if active_target_depth > 0:
            filename = frame.f_code.co_filename
            if under_src_pybamm(filename):
                if '<' not in qual and '>' not in qual:
                    func = f"{modname}.{qual}"
                    if func.startswith(prefixes):
                        covered.add((norm_rel(filename), func))
    elif event in ('return', 'exception'):
        key = id(frame)
        is_target = is_target_frame_stack.pop(key, False)
        if is_target and active_target_depth > 0:
            active_target_depth -= 1
    return profiler

sys.setprofile(profiler)
try:
    for i in range(1, 11):
        getattr(obj, f'test_case_{i:02d}')()
finally:
    sys.setprofile(None)

result = [
    {'file': file, 'func': func}
    for file, func in sorted(covered, key=lambda x: (x[0], x[1]))
]
print(json.dumps(result, indent=2))
print('COUNT', len(result))
